def comps(g, eight=True):
 h,w=len(g),len(g[0]); dirs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (eight or abs(dr)+abs(dc)==1)]
 seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c] and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); pts=[]
    while q:
     x,y=q.pop(); pts.append((x,y))
     for dr,dc in dirs:
      z=(x+dr,y+dc)
      if 0<=z[0]<h and 0<=z[1]<w and g[z[0]][z[1]] and z not in seen: seen.add(z); q.append(z)
    out.append(pts)
 return out
