def stats(g):
 cs=comps(g,True); out=[]
 for pts in cs:
  rs=[r for r,c in pts]; xx=[c for r,c in pts]; r0,r1,c0,c1=min(rs),max(rs),min(xx),max(xx); H=r1-r0+1;W=c1-c0+1
  a={(r-r0,c-c0) for r,c in pts}
  # 4-connected count
  remain=set(a); n4=0
  while remain:
   n4+=1; todo=[remain.pop()]
   while todo:
    r,c=todo.pop()
    for q in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
     if q in remain: remain.remove(q); todo.append(q)
  v=sum((r,c) in a and (r,W-1-c) in a for r,c in a) # no
  symh=all((r,W-1-c) in a for r,c in a) # vertical axis
  symv=all((H-1-r,c) in a for r,c in a)
  sym180=all((H-1-r,W-1-c) in a for r,c in a)
  # bbox perimeter occupancy
  border=sum(r in (0,H-1) or c in (0,W-1) for r,c in a)
  out.append(dict(area=len(a),box=(H,W),density=round(len(a)/(H*W),3),n4=n4,symx=symh,symy=symv,sym180=sym180,border=border,profile=[sum((r,c) in a for c in range(W)) for r in range(H)]))
 return out
